EOF"

/bin/bash -lc "node --input-type=module <<'EOF'
const cases = [
  ['/products/lamp', 'Brass lamp', 'USD 120.00', 'Stone vase'],
  ['/products/lamp?currency=EUR', 'Brass lamp', 'EUR 110.40', 'Stone vase'],
  ['/products/vase?currency=USD', 'Stone vase', 'USD 80.00', 'Brass lamp'],
  ['/products/vase?currency=EUR', 'Stone vase', 'EUR 73.60', 'Brass lamp'],
]
for (const [path, name, price, related] of cases) {
  const response = await fetch('http://localhost:3100' + path)
  const chunks = []
  for await (const chunk of response.body) chunks.push(new TextDecoder().decode(chunk))
  const html = chunks.join('')
  const first = chunks[0]
  const markers = [
    '<h1>' + name + '</h1>',
    '<p>' + price + '</p>',
    '<p>Loading related products…</p>',
    '<p>' + related + '</p>',
  ]
  const positions = markers.map((marker) => html.indexOf(marker))
  const valid = response.status === 200 && first.includes('Signal Shop collection') && first.includes('Loading product') && positions.every((i) => i >= 0) && positions.every((i, index) => index === 0 || i > positions[index - 1])
  console.log(path, JSON.stringify({ status: response.status, chunks: chunks.length, valid }))
  if ("'!valid) process.exitCode = 1
}
EOF'

